-- Suwar Irrigation System - MySQL schema + sample data (generated by database/generate_schema.py)
-- Run with:  mysql -u root -p < database/schema.sql   (or: python setup_database.py)

DROP DATABASE IF EXISTS suwar;
CREATE DATABASE suwar CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE suwar;

CREATE TABLE Sensors (
    sensor_id       INT PRIMARY KEY,
    location        VARCHAR(100) NOT NULL,
    falaj_name      VARCHAR(100) NOT NULL,
    value           DOUBLE NOT NULL DEFAULT 0.0,
    status          VARCHAR(20) NOT NULL DEFAULT 'Normal',
    last_calibrated DATETIME NULL
) ENGINE=InnoDB;

CREATE TABLE Gates (
    gate_id    INT PRIMARY KEY,
    location   VARCHAR(100) NOT NULL,
    falaj_name VARCHAR(100) NOT NULL,
    is_open    TINYINT(1) NOT NULL DEFAULT 0,
    flow_rate  DOUBLE NOT NULL DEFAULT 0.0
) ENGINE=InnoDB;

CREATE TABLE Farms (
    farm_id    INT PRIMARY KEY,
    location   VARCHAR(100) NOT NULL,
    falaj_name VARCHAR(100) NOT NULL,
    size       DOUBLE NOT NULL
) ENGINE=InnoDB;

CREATE TABLE Users (
    user_id       INT PRIMARY KEY,
    username      VARCHAR(50)  NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    name          VARCHAR(100) NOT NULL,
    role          VARCHAR(30)  NOT NULL,
    access_level  INT NOT NULL DEFAULT 1,
    farm_id       INT NULL,
    FOREIGN KEY (farm_id) REFERENCES Farms(farm_id)
) ENGINE=InnoDB;

CREATE TABLE TimeSlots (
    slot_id     INT PRIMARY KEY,
    start_time  VARCHAR(5)   NOT NULL,
    falaj_name  VARCHAR(100) NOT NULL,
    reserved_by INT NULL,
    FOREIGN KEY (reserved_by) REFERENCES Users(user_id),
    UNIQUE KEY uq_slot_time (falaj_name, start_time)
) ENGINE=InnoDB;

CREATE TABLE Maintenance (
    maintenance_id INT AUTO_INCREMENT PRIMARY KEY,
    sensor_id      INT NOT NULL,
    issue_type     VARCHAR(50)  NOT NULL,
    reported_date  DATETIME     NOT NULL,
    status         VARCHAR(20)  NOT NULL DEFAULT 'Open',
    location       VARCHAR(200) NOT NULL,
    scheduled_date DATE NULL,
    FOREIGN KEY (sensor_id) REFERENCES Sensors(sensor_id),
    INDEX idx_maint_sensor_time (sensor_id, reported_date),
    INDEX idx_maint_status (status)
) ENGINE=InnoDB;

CREATE TABLE SensorReadings (
    reading_id  INT AUTO_INCREMENT PRIMARY KEY,
    sensor_id   INT NOT NULL,
    value       DOUBLE NOT NULL,
    recorded_at DATETIME NOT NULL,
    FOREIGN KEY (sensor_id) REFERENCES Sensors(sensor_id),
    INDEX idx_reading_sensor (sensor_id, reading_id)
) ENGINE=InnoDB;

CREATE TABLE Reports (
    report_id      INT AUTO_INCREMENT PRIMARY KEY,
    report_type    VARCHAR(50) NOT NULL,
    generated_date DATETIME NOT NULL,
    payload        LONGTEXT NOT NULL,          -- encrypted JSON (DataSecurity)
    user_id        INT NULL,
    FOREIGN KEY (user_id) REFERENCES Users(user_id)
) ENGINE=InnoDB;






